"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[2662],{60450(t,e,a){a.r(e),a.d(e,{comp:()=>d,data:()=>o});var n=a(20641);const s=a.p+"assets/img/admin-staff-settings.976eaba6.png",l=a.p+"assets/img/admin-vendor-staffs-list.52950a27.png",r=a.p+"assets/img/admin-vendor-staff-edit.18a3a80f.png",i={},d=(0,a(66262).A)(i,[["render",function(t,e){return(0,n.uX)(),(0,n.CE)("div",null,e[0]||(e[0]=[(0,n.Fv)('<h1 id="configuration-–-staff-settings" tabindex="-1"><a class="header-anchor" href="#configuration-–-staff-settings"><span>Configuration – Staff Settings</span></a></h1><p>The <strong>Staff Settings</strong> tab allows marketplace administrators to govern the sub-account (vendor staff) ecosystem. Admins can globally enable or disable the staff feature, set quotas on the maximum number of assistants each vendor may employ, define the global whitelist of delegatable capabilities across all marketplace modules (including Seller Dashboard, Products, Select And Sell, Bulk Upload, Orders, and more), and directly oversee, edit, or remove all vendor staff accounts across the marketplace.</p><p>The marketplace admin can access and configure this section from:</p><p><strong>Marketplace &gt; Settings &gt; Staffs</strong></p><p><strong>Direct Admin Navigation URLs</strong>:</p><ul><li><strong>Staff Settings Tab</strong>: <code>wp-admin/admin.php?page=wk-marketplace-settings&amp;tab=staff</code></li><li><strong>Vendor Staffs Management List</strong>: <code>wp-admin/admin.php?page=wk-marketplace-vendor-staffs</code></li></ul><p><a class="doc-image-link" href="./assets/admin-staff-settings.png"><img src="'+s+'" alt="Admin Staff Settings"></a></p><hr><h2 id="staff-settings-overview" tabindex="-1"><a class="header-anchor" href="#staff-settings-overview"><span>Staff Settings Overview</span></a></h2><ul><li><strong>Global Staff Control</strong>: Enable or disable the vendor staff management feature across the entire marketplace.</li><li><strong>Per-Vendor Staff Limits</strong>: Configure maximum staff accounts allowed per vendor, or set to <code>0</code> for unlimited team members.</li><li><strong>Granular Delegatable Permissions</strong>: Control which permissions vendors are allowed to pass on to their staff across core modules and operational sections.</li><li><strong>Consolidated Dashboard Permissions</strong>: Manage access to the modern Seller Panel, store performance metrics, sales reports, customer lists, Magic AI tools, and storefront appearance from a unified Seller Dashboard card.</li><li><strong>Select &amp; Sell and Bulk Upload Controls</strong>: Safely delegate existing catalog listing management and CSV batch processing to staff members.</li><li><strong>Sensitive Permission Guardrails</strong>: Critical capabilities (such as editing payment/payout information and managing KYC identity documents) are marked in red and left disabled by default for security.</li><li><strong>Interactive Matrix Tools</strong>: One-click <strong>Select all</strong> and <strong>Deselect all</strong> toggles on each capability card for rapid permission configuration.</li><li><strong>Centralized Staff Registry</strong>: Comprehensive admin list to review, search, sort, and bulk-delete vendor staff across all sellers.</li><li><strong>Administrative Override &amp; Editing</strong>: Directly view and edit any staff member&#39;s profile details and fine-tune their individual permission set.</li><li><strong>Per-Vendor Override</strong>: Selectively enable or disable staff functionality for individual vendors through their seller profile, even when global staff access is disabled.</li><li><strong>Customizable Dashboard Endpoint</strong>: Tailor the front-end dashboard URL slug and menu title for the vendor staff section.</li></ul><div class="hint-container tip"><p class="hint-container-title">Vendor Guide Reference</p><p>To learn how vendors create staff accounts, assign roles, and delegate daily shop responsibilities from their seller dashboard, refer to the <a href="/documentation/vendor-staff" target="_blank" rel="noopener noreferrer">Vendor Staff Guide</a>.</p></div><hr><h2 id="admin-staff-settings-summary" tabindex="-1"><a class="header-anchor" href="#admin-staff-settings-summary"><span>Admin Staff Settings Summary</span></a></h2><p>The table below provides a quick reference for each setting available on the <strong>Staffs</strong> configuration tab:</p><table><thead><tr><th style="text-align:left;">Setting Label</th><th style="text-align:left;">Input Type</th><th style="text-align:left;">Default Setting</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enable Vendor Staff</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Enabled (Checked)</td><td style="text-align:left;">Globally activates the vendor staff feature for all vendors. When disabled, only vendors individually enabled in their Miscellaneous/Seller settings can add staff.</td></tr><tr><td style="text-align:left;"><strong>Max Staff Per Vendor</strong></td><td style="text-align:left;">Number Field</td><td style="text-align:left;"><code>0</code> (Unlimited)</td><td style="text-align:left;">Sets the maximum number of staff accounts an individual vendor can create. Set to <code>0</code> for unlimited staff members.</td></tr><tr><td style="text-align:left;"><strong>Delegatable Permissions</strong></td><td style="text-align:left;">Interactive Card Grid</td><td style="text-align:left;">All Standard Checked (Sensitive Unchecked)</td><td style="text-align:left;">Defines the marketplace-wide pool of permissions vendors can delegate to staff. Vendors can only grant permissions enabled here.</td></tr><tr><td style="text-align:left;"><strong>Save Changes</strong></td><td style="text-align:left;">Primary Button</td><td style="text-align:left;">Click to Save</td><td style="text-align:left;">Immediately applies and stores the updated global staff settings.</td></tr></tbody></table><hr><h2 id="admin-staff-settings" tabindex="-1"><a class="header-anchor" href="#admin-staff-settings"><span>Admin Staff Settings</span></a></h2><h3 id="enable-vendor-staff" tabindex="-1"><a class="header-anchor" href="#enable-vendor-staff"><span>Enable Vendor Staff</span></a></h3><ul><li><strong>Setting Type</strong>: Checkbox</li><li><strong>Default State</strong>: Enabled (Checked)</li><li><strong>Live Description</strong>: <em>&quot;Allow vendors to add vendor staff staff. When off, only vendors individually enabled in their Miscellaneous settings can use it.&quot;</em></li></ul><h4 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works"><span>How It Works:</span></a></h4><ul><li><strong>When Enabled</strong>: Every registered marketplace vendor gains access to the <strong>Vendor Staff</strong> menu in their front-end seller dashboard. Vendors can create sub-accounts, invite store assistants, and delegate daily operations.</li><li><strong>When Disabled</strong>: The <strong>Vendor Staff</strong> tab is hidden from seller dashboards across the marketplace. Existing staff members cannot log in to perform restricted seller actions.</li><li><strong>Per-Vendor Exception Mode</strong>: If the global setting is disabled, administrators can still selectively allow trusted or enterprise vendors to create staff accounts by enabling the permission within the vendor&#39;s individual <strong>Seller Details</strong> settings under <strong>Marketplace &gt; Sellers</strong>.</li></ul><hr><h3 id="max-staff-per-vendor" tabindex="-1"><a class="header-anchor" href="#max-staff-per-vendor"><span>Max Staff Per Vendor</span></a></h3><ul><li><strong>Setting Type</strong>: Number Field</li><li><strong>Default Value</strong>: <code>0</code></li><li><strong>Live Description</strong>: <em>&quot;0 means unlimited.&quot;</em></li></ul><h4 id="how-it-works-1" tabindex="-1"><a class="header-anchor" href="#how-it-works-1"><span>How It Works:</span></a></h4><ul><li><strong>Unlimited Quota (<code>0</code>)</strong>: Vendors can register as many staff members as their operations require without system restriction.</li><li><strong>Numeric Limit (<code>1, 2, 5, etc.</code>)</strong>: Caps the number of active staff accounts a vendor can maintain.</li><li>When a vendor reaches the configured limit, the seller dashboard disables the <strong>Add Staff</strong> action and notifies the vendor that their account allocation is exhausted.</li><li>This setting is valuable for marketplace owners offering tiered membership plans (e.g., Free sellers receive 1 staff account, while Premium sellers enjoy expanded allocations).</li></ul><hr><h3 id="delegatable-permissions-matrix" tabindex="-1"><a class="header-anchor" href="#delegatable-permissions-matrix"><span>Delegatable Permissions Matrix</span></a></h3><ul><li><strong>Setting Type</strong>: Collapsible Capability Cards with Select/Deselect Controls</li><li><strong>Live Description</strong>: <em>&quot;Permissions a vendor may delegate to staff. Vendors pick per staff from this set. Permissions shown in red are sensitive and are not granted by default.&quot;</em></li></ul><h4 id="operational-hierarchy" tabindex="-1"><a class="header-anchor" href="#operational-hierarchy"><span>Operational Hierarchy:</span></a></h4><p>The <strong>Delegatable Permissions</strong> setting acts as a master security boundary for the entire marketplace:</p><ol><li><strong>Admin Master Whitelist</strong>: Marketplace admins select the broad pool of capabilities that are safe for vendors to delegate.</li><li><strong>Vendor Sub-Assignment</strong>: When vendors create or edit an assistant in their dashboard, they can <em>only</em> choose from the capabilities permitted by the admin here.</li><li>If an admin unchecks a permission here, it is automatically revoked from all vendor staff members, even if a vendor previously selected it.</li></ol><h4 id="capability-modules-permissions-breakdown" tabindex="-1"><a class="header-anchor" href="#capability-modules-permissions-breakdown"><span>Capability Modules &amp; Permissions Breakdown:</span></a></h4><p>The matrix is organized into clean functional cards matching the marketplace architecture:</p><table><thead><tr><th style="text-align:left;">Functional Section</th><th style="text-align:left;">Capability Name</th><th style="text-align:left;">Sensitivity &amp; Default Status</th><th style="text-align:left;">Operational Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Seller Dashboard</strong></td><td style="text-align:left;">Access New Seller Panel</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Grants access to log in and use the modernized <a href="/documentation/seller-panel-overview" target="_blank" rel="noopener noreferrer">Seller Dashboard</a> interface and primary metrics.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Performance</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows staff to view store performance charts, visitor trends, and conversion analytics.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Reporting</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes viewing detailed sales reporting, top product revenue, and customer metrics.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Customers</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Gives access to view customer contact lists and customer purchase history.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Magic AI</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes staff to use AI-assisted product and content generation tools. For details, see <a href="/documentation/generative-ai-overview" target="_blank" rel="noopener noreferrer">Generative AI Overview</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">General Setting</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows updating core seller profile details, shop address, and contact information.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Graph Setting</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows customizing the visual color schemes of sales analytics charts.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Site Setting</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits adjusting vendor storefront appearance, banners, and layout options.</td></tr><tr><td style="text-align:left;"><strong>Products</strong></td><td style="text-align:left;">View products</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows staff to view the vendor&#39;s catalog product list. See <a href="/documentation/vendor-product-management" target="_blank" rel="noopener noreferrer">Vendor Product Management</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Add product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Enables creation of new product listings.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Edit product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows updating existing product details, pricing, inventory, and images.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Delete product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits trashing or permanently deleting vendor products.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Publish product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows direct publishing of products without requiring admin moderation.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Generate barcodes</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Enables generation of product barcode identifiers. See <a href="/documentation/product-barcode" target="_blank" rel="noopener noreferrer">Product Barcode Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Print barcodes</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows downloading and printing barcode labels.</td></tr><tr><td style="text-align:left;"><strong>Select And Sell</strong></td><td style="text-align:left;">View listing</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Grants visibility to search and view existing marketplace products available to claim. See <a href="/documentation/admin-select-and-sell" target="_blank" rel="noopener noreferrer">Admin Select and Sell</a> and <a href="/documentation/selling-existing-products" target="_blank" rel="noopener noreferrer">Selling Existing Products</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Add product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes staff to assign existing products to the vendor&#39;s store catalog.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Edit product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows modifying vendor-specific stock, condition, and pricing on assigned catalog items.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Delete product</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits removing assigned products from the vendor&#39;s active offerings.</td></tr><tr><td style="text-align:left;"><strong>Bulk Upload</strong></td><td style="text-align:left;">Normal Products</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes importing and exporting standard marketplace catalog items in bulk via CSV/XML spreadsheets. See <a href="/documentation/bulk-upload" target="_blank" rel="noopener noreferrer">Bulk Upload Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Select And Sell</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits batch claiming and assigning existing catalog products via CSV spreadsheets.</td></tr><tr><td style="text-align:left;"><strong>Orders</strong></td><td style="text-align:left;">View orders</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Grants visibility into customer orders containing the vendor&#39;s items. See <a href="/documentation/vendor-order-management" target="_blank" rel="noopener noreferrer">Vendor Order Management</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Change order status</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows updating fulfillment progress (e.g., Processing to Completed).</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Refund order</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes staff to process customer refund requests.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Print invoice</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows printing vendor packaging slips and invoices. See <a href="/documentation/configuration-vendor-invoice" target="_blank" rel="noopener noreferrer">Configuration – Vendor Invoice</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Schedule pickups</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits scheduling carrier collection for dispatched packages. See <a href="/documentation/fulfilment-carriers" target="_blank" rel="noopener noreferrer">Fulfilment Carriers Guide</a>.</td></tr><tr><td style="text-align:left;"><strong>Transactions</strong></td><td style="text-align:left;">View transaction list</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows staff to view payment withdrawal logs and history. See <a href="/documentation/vendor-transaction-management" target="_blank" rel="noopener noreferrer">Vendor Transaction Management</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">View transaction details</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits inspecting granular payout breakdown details.</td></tr><tr><td style="text-align:left;"><strong>Vacation</strong></td><td style="text-align:left;">View vacations</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Displays the vendor vacation schedule and history. See <a href="/documentation/vendor-vacation" target="_blank" rel="noopener noreferrer">Vendor Vacation Guide</a> and <a href="/documentation/admin-vacation-setting" target="_blank" rel="noopener noreferrer">Admin Vacation Settings</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Add vacation</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Enables scheduling a new store holiday or temporary closure.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Edit vacation</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows modifying holiday dates and storefront closure messages.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Delete vacation</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits canceling scheduled vacations.</td></tr><tr><td style="text-align:left;"><strong>Shop Followers</strong></td><td style="text-align:left;">View followers</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows viewing customer accounts that follow the store. See <a href="/documentation/vendor-shop-followers" target="_blank" rel="noopener noreferrer">Vendor Shop Followers Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Remove followers</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows removing individual follower entries.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Send notification to followers</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits broadcasting promotional updates or store announcements to followers.</td></tr><tr><td style="text-align:left;"><strong>Notifications</strong></td><td style="text-align:left;">View notifications</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Grants access to view low-stock notices, order events, and system alerts. See <a href="/documentation/vendor-notification" target="_blank" rel="noopener noreferrer">Vendor Notification Guide</a>.</td></tr><tr><td style="text-align:left;"><strong>My Profile</strong></td><td style="text-align:left;">View profile</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Displays public shop details and seller configuration. See <a href="/documentation/vendor-profile" target="_blank" rel="noopener noreferrer">Vendor Profile Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Edit profile</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows updating banner images, shop descriptions, and contact addresses.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Edit payment information</td><td style="text-align:left;"><span style="color:#d63638;font-weight:600;">Sensitive (Unchecked)</span></td><td style="text-align:left;">Allows modifying bank accounts, PayPal emails, or payout destination credentials. See <a href="/documentation/vendor-payout-management" target="_blank" rel="noopener noreferrer">Vendor Payout Management</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Manage KYC documents</td><td style="text-align:left;"><span style="color:#d63638;font-weight:600;">Sensitive (Unchecked)</span></td><td style="text-align:left;">Allows uploading, replacing, or viewing confidential merchant identity verifications. See <a href="/documentation/vendor-kyc" target="_blank" rel="noopener noreferrer">Vendor KYC Guide</a>.</td></tr><tr><td style="text-align:left;"><strong>Ask Admin</strong></td><td style="text-align:left;">View query list</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Displays existing support query threads between vendor and marketplace admin. See <a href="/documentation/ask-to-admin" target="_blank" rel="noopener noreferrer">Ask to Admin Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">View query thread</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Opens detailed back-and-forth query conversations.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Create new query</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows initiating a new support inquiry with marketplace administrators.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Reply to query</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits sending replies within an existing support inquiry thread.</td></tr><tr><td style="text-align:left;"><strong>Shippings</strong></td><td style="text-align:left;">View shipping</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Displays configured shipping methods, zones, and rates. See <a href="/documentation/vendor-shipping-zone-management" target="_blank" rel="noopener noreferrer">Vendor Shipping Zone Management</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Manage shipping zones</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows adding, modifying, or deleting regional delivery zones.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Manage shipping classes</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Permits creating and adjusting shipping classes and delivery fees.</td></tr><tr><td style="text-align:left;"><strong>Admin News</strong></td><td style="text-align:left;">View news list</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Grants access to read marketplace announcements and news broadcasts. See <a href="/documentation/admin-news" target="_blank" rel="noopener noreferrer">Admin News Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">View news details</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Allows reading complete news articles and policy bulletins.</td></tr><tr><td style="text-align:left;"><strong>Store Pickup</strong> <em>(Modular)</em></td><td style="text-align:left;">View store pickup orders</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Displays local store collection orders placed by shoppers when the Store Pickup module is active. See <a href="/documentation/store-pickup-settings" target="_blank" rel="noopener noreferrer">Store Pickup Settings</a> and <a href="/documentation/admin-store-pickup" target="_blank" rel="noopener noreferrer">Admin Store Pickup Guide</a>.</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Send and verify pickup codes</td><td style="text-align:left;">Standard (Checked)</td><td style="text-align:left;">Authorizes validating one-time customer pickup verification PINs at the store collection counter.</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">Sensitive Capabilities Safeguard</p><p>Capabilities displayed with red text (<strong>Edit payment information</strong> and <strong>Manage KYC documents</strong>) represent elevated financial and legal risks. They are deliberately excluded from default permissions. Only enable these if your marketplace workflow requires vendor accountants or legal staff to manage payout channels and verification paperwork.</p></div><hr><h2 id="per-vendor-staff-override" tabindex="-1"><a class="header-anchor" href="#per-vendor-staff-override"><span>Per-Vendor Staff Override</span></a></h2><p>Marketplace administrators can override the global <strong>Enable Vendor Staff</strong> setting for individual vendors. This is useful when the marketplace owner wants to keep staff accounts disabled globally, but selectively allow verified, VIP, or higher-tier sellers to add staff.</p><h3 id="how-to-configure-per-vendor-staff-access" tabindex="-1"><a class="header-anchor" href="#how-to-configure-per-vendor-staff-access"><span>How to Configure Per-Vendor Staff Access:</span></a></h3><ol><li>Navigate to <strong>Marketplace &gt; Sellers</strong> in the WordPress admin panel.</li><li>Hover over the target seller and click <strong>Edit</strong>.</li><li>Under the seller details form, locate the <strong>Vendor Staff</strong> field: <ul><li><strong>Default (Global setting)</strong>: Follows the global toggle set in <strong>Marketplace &gt; Settings &gt; Staffs</strong>.</li><li><strong>Enabled</strong>: Explicitly grants this vendor permission to manage staff members and assign delegated roles, regardless of the global marketplace setting.</li><li><strong>Disabled</strong>: Explicitly revokes staff management for this vendor, preventing them from adding or using staff sub-accounts even if the global marketplace setting is active.</li></ul></li><li>Click <strong>Update</strong> to save the seller&#39;s configuration.</li></ol><hr><h2 id="admin-vendor-staffs-management" tabindex="-1"><a class="header-anchor" href="#admin-vendor-staffs-management"><span>Admin Vendor Staffs Management</span></a></h2><p>Marketplace administrators have centralized visibility over every staff account registered across all vendors in the marketplace.</p><p>To inspect and manage all vendor assistants, navigate to:</p><p><strong>Marketplace &gt; Vendor Staffs</strong></p><p><strong>Direct Admin Navigation URL</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">wp-admin/admin.php?page=wk-marketplace-vendor-staffs</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><a class="doc-image-link" href="./assets/admin-vendor-staffs-list.png"><img src="'+l+'" alt="Admin Vendor Staffs List"></a></p><h3 id="vendor-staffs-list-features" tabindex="-1"><a class="header-anchor" href="#vendor-staffs-list-features"><span>Vendor Staffs List Features</span></a></h3><p>The table provides complete administrative oversight of multi-vendor staff members:</p><ol><li><p><strong>Table Columns</strong>:</p><ul><li><strong>Checkbox</strong>: Allows selecting individual or multiple records for bulk actions.</li><li><strong>Name</strong>: The display name of the staff member. Hovering over a name reveals quick action links (<code>Edit</code> and <code>Delete</code>). Supports ascending/descending sorting.</li><li><strong>Email</strong>: The registered user email address utilized for staff authentication. Supports ascending/descending sorting.</li><li><strong>Vendor</strong>: The parent vendor store (e.g., <em>Aurora Athletics</em>) to which the staff member belongs.</li><li><strong>Access</strong>: A comma-delimited summary of all active capabilities currently granted to this staff user.</li></ul></li><li><p><strong>Search Staff Members</strong>:</p><ul><li>Use the search bar in the top-right corner of the table to quickly locate assistants across all vendors by <strong>Name</strong>, <strong>Username</strong>, or <strong>Email address</strong>.</li></ul></li><li><p><strong>Bulk Actions</strong>:</p><ul><li>Select multiple staff rows using the checkboxes.</li><li>Choose <strong>Delete</strong> from the bulk actions dropdown and click <strong>Apply</strong> to remove compromised or inactive staff accounts across the marketplace.</li></ul></li><li><p><strong>Screen Options</strong>:</p><ul><li>Click the <strong>Screen Options</strong> pull-down tab in the top-right corner to toggle column visibility (<strong>Email</strong>, <strong>Vendor</strong>, <strong>Access</strong>) or adjust the pagination threshold (<strong>Items per page</strong>, default <code>20</code>).</li></ul></li></ol><hr><h2 id="editing-a-vendor-staff-member-from-admin" tabindex="-1"><a class="header-anchor" href="#editing-a-vendor-staff-member-from-admin"><span>Editing a Vendor Staff Member from Admin</span></a></h2><p>Administrators can inspect, modify, or override any vendor staff account directly from the WordPress back-office without logging into the seller dashboard.</p><p>To edit a staff account:</p><ol><li>Navigate to <strong>Marketplace &gt; Vendor Staffs</strong>.</li><li>Hover over the staff member&#39;s name and click <strong>Edit</strong>.</li></ol><p><strong>Direct Admin Edit URL</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">wp-admin/admin.php?page=wk-marketplace-vendor-staffs&amp;section=edit&amp;staff_id={ID}</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><a class="doc-image-link" href="./assets/admin-vendor-staff-edit.png"><img src="'+r+'" alt="Edit Vendor Staff"></a></p><h3 id="edit-staff-field-breakdown" tabindex="-1"><a class="header-anchor" href="#edit-staff-field-breakdown"><span>Edit Staff Field Breakdown</span></a></h3><p>The Edit Vendor Staff screen provides administrative control over personal details and permissions:</p><table><thead><tr><th style="text-align:left;">Field Label</th><th style="text-align:left;">Control Type</th><th style="text-align:left;">Modifiable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Name</strong></td><td style="text-align:left;">Text Input (<code>wkmp_staff_first_name</code>)</td><td style="text-align:left;">Yes</td><td style="text-align:left;">The first name or operational label for the staff account.</td></tr><tr><td style="text-align:left;"><strong>Email</strong></td><td style="text-align:left;">Plain Text Display</td><td style="text-align:left;">Read-only</td><td style="text-align:left;">Displays the unique login email address tied to the WordPress user account.</td></tr><tr><td style="text-align:left;"><strong>Vendor</strong></td><td style="text-align:left;">Plain Text Display</td><td style="text-align:left;">Read-only</td><td style="text-align:left;">Displays the parent vendor store to which the staff member is bound.</td></tr><tr><td style="text-align:left;"><strong>Access</strong></td><td style="text-align:left;">Interactive Capability Matrix</td><td style="text-align:left;">Yes</td><td style="text-align:left;">Complete grid of capability cards. Admins can grant or revoke any capability specifically for this staff user.</td></tr><tr><td style="text-align:left;"><strong>Update Staff</strong></td><td style="text-align:left;">Primary Button</td><td style="text-align:left;">Action</td><td style="text-align:left;">Immediately saves all modified details and updates the staff member&#39;s permissions.</td></tr></tbody></table><h4 id="administrative-override-capabilities" tabindex="-1"><a class="header-anchor" href="#administrative-override-capabilities"><span>Administrative Override Capabilities:</span></a></h4><ul><li>Even if a seller omitted a permission when adding their assistant, an administrator can check the capability here and click <strong>Update Staff</strong> to grant it.</li><li>Conversely, if an assistant misbehaves or requires immediate restriction, an admin can uncheck capabilities (such as <em>Delete product</em> or <em>Refund order</em>) to instantly restrict their access without deleting the staff account.</li></ul><hr><h2 id="customizing-the-vendor-staff-endpoint" tabindex="-1"><a class="header-anchor" href="#customizing-the-vendor-staff-endpoint"><span>Customizing the Vendor Staff Endpoint</span></a></h2><p>Administrators can customize the URL slug and menu label that vendors use to access the staff section in their dashboard.</p><p>To adjust the endpoint:</p><ol><li>Navigate to <strong>Marketplace &gt; Settings &gt; Endpoints</strong>.</li><li>Locate the <strong>Vendor Staff</strong> row.</li></ol><p><strong>Endpoint Parameters</strong>:</p><ul><li><strong>Default Endpoint Slug</strong>: <code>vendor-staff</code></li><li><strong>Default Menu Title</strong>: <code>Vendor Staff</code></li><li><strong>Resolved URL</strong>: <code>https://example.com/seller/vendor-staff/</code> (or <code>https://example.com/my-account/vendor-staff/</code>)</li></ul><p>For more details on managing dashboard URL routing, consult the <a href="/documentation/configuration-endpoints" target="_blank" rel="noopener noreferrer">Endpoints Configuration Guide</a>.</p><hr><h2 id="best-practices-for-marketplace-administrators" tabindex="-1"><a class="header-anchor" href="#best-practices-for-marketplace-administrators"><span>Best Practices for Marketplace Administrators</span></a></h2><ol><li><p><strong>Keep Sensitive Capabilities Disabled</strong>: Always keep <strong>Edit payment information</strong> and <strong>Manage KYC documents</strong> unchecked in the global Delegatable Permissions matrix unless there is a verified business requirement. This prevents rogue staff members from altering a vendor&#39;s payout destination.</p></li><li><p><strong>Establish Reasonable Staff Quotas</strong>: Set a sensible limit in <strong>Max Staff Per Vendor</strong> (e.g., <code>3</code> to <code>5</code>) rather than leaving it at <code>0</code> (unlimited) if your marketplace server resources are constrained or if you plan to monetize sub-accounts via tiered vendor subscription plans.</p></li><li><p><strong>Utilize Select &amp; Sell and Bulk Upload Delegation Carefully</strong>: Allowing staff to access <strong>Bulk Upload</strong> and <strong>Select And Sell</strong> can accelerate seller onboarding, but ensure only trusted assistants have permission to delete items or perform mass imports.</p></li><li><p><strong>Leverage Per-Vendor Overrides</strong>: If you wish to test staff management with a small group of sellers, leave the global <strong>Enable Vendor Staff</strong> option turned off and enable staff access selectively for individual vendors under <strong>Marketplace &gt; Sellers</strong>.</p></li><li><p><strong>Audit Staff Permissions Regularly</strong>: Periodically review the <strong>Marketplace &gt; Vendor Staffs</strong> list to check which assistants have broad capabilities, especially <em>Refund order</em> and <em>Publish product</em>.</p></li><li><p><strong>Coordinate with Vendor Guides</strong>: Direct your sellers to the <a href="/documentation/vendor-staff" target="_blank" rel="noopener noreferrer">Vendor Staff Guide</a> so they understand how to invite staff, generate strong passwords, and manage permissions from their store management panel.</p></li></ol>',76)]))}]]),o=JSON.parse('{"path":"/documentation/admin-staff-setting.html","title":"Configuration – Staff Settings","lang":"en-US","frontmatter":{"title":"Configuration – Staff Settings","description":"Configure vendor staff settings in WooCommerce Multi-Vendor Marketplace. Manage global staff access, max staff limits, delegatable permissions matrix, and admin vendor staff operations.","head":[["meta",{"name":"keywords","content":"woocommerce marketplace staff settings, admin vendor staff configuration, multi vendor staff management, vendor sub accounts woocommerce, marketplace delegatable permissions, vendor staff permissions matrix woocommerce, admin vendor staffs, select and sell staff permissions, bulk upload staff capabilities, magic ai vendor staff"}],["meta",{"property":"og:title","content":"Configuration – Staff Settings | WooCommerce Multi-Vendor Marketplace"}],["meta",{"property":"og:description","content":"Configure vendor staff settings in WooCommerce Multi-Vendor Marketplace. Manage global staff access, max staff limits, delegatable permissions matrix, and admin vendor staff operations."}],["meta",{"property":"og:type","content":"article"}]]},"headers":[{"level":2,"title":"Staff Settings Overview","slug":"staff-settings-overview","link":"#staff-settings-overview","children":[]},{"level":2,"title":"Admin Staff Settings Summary","slug":"admin-staff-settings-summary","link":"#admin-staff-settings-summary","children":[]},{"level":2,"title":"Admin Staff Settings","slug":"admin-staff-settings","link":"#admin-staff-settings","children":[{"level":3,"title":"Enable Vendor Staff","slug":"enable-vendor-staff","link":"#enable-vendor-staff","children":[]},{"level":3,"title":"Max Staff Per Vendor","slug":"max-staff-per-vendor","link":"#max-staff-per-vendor","children":[]},{"level":3,"title":"Delegatable Permissions Matrix","slug":"delegatable-permissions-matrix","link":"#delegatable-permissions-matrix","children":[]}]},{"level":2,"title":"Per-Vendor Staff Override","slug":"per-vendor-staff-override","link":"#per-vendor-staff-override","children":[{"level":3,"title":"How to Configure Per-Vendor Staff Access:","slug":"how-to-configure-per-vendor-staff-access","link":"#how-to-configure-per-vendor-staff-access","children":[]}]},{"level":2,"title":"Admin Vendor Staffs Management","slug":"admin-vendor-staffs-management","link":"#admin-vendor-staffs-management","children":[{"level":3,"title":"Vendor Staffs List Features","slug":"vendor-staffs-list-features","link":"#vendor-staffs-list-features","children":[]}]},{"level":2,"title":"Editing a Vendor Staff Member from Admin","slug":"editing-a-vendor-staff-member-from-admin","link":"#editing-a-vendor-staff-member-from-admin","children":[{"level":3,"title":"Edit Staff Field Breakdown","slug":"edit-staff-field-breakdown","link":"#edit-staff-field-breakdown","children":[]}]},{"level":2,"title":"Customizing the Vendor Staff Endpoint","slug":"customizing-the-vendor-staff-endpoint","link":"#customizing-the-vendor-staff-endpoint","children":[]},{"level":2,"title":"Best Practices for Marketplace Administrators","slug":"best-practices-for-marketplace-administrators","link":"#best-practices-for-marketplace-administrators","children":[]}],"git":{},"filePathRelative":"documentation/admin-staff-setting.md"}')}}]);